import{_ as a,c as r,o as t,ag as i}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"AI Resources","description":"","frontmatter":{"title":"AI Resources"},"headers":[],"relativePath":"ai-ml/ai-resources.md","filePath":"ai-ml/ai-resources.md","lastUpdated":null}'),l={name:"ai-ml/ai-resources.md"};function o(n,e,s,h,c,g){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-resources" tabindex="-1">AI Resources <a class="header-anchor" href="#ai-resources" aria-label="Permalink to &quot;AI Resources&quot;">​</a></h1><h2 id="ai-ml-resources" tabindex="-1">AI/ML Resources <a class="header-anchor" href="#ai-ml-resources" aria-label="Permalink to &quot;AI/ML Resources&quot;">​</a></h2><p>This is the community AI/ML section. It is a comprehensive guide to getting started with AI and ML.</p><h3 id="learning-ai-ml" tabindex="-1">Learning AI/ML <a class="header-anchor" href="#learning-ai-ml" aria-label="Permalink to &quot;Learning AI/ML&quot;">​</a></h3><ul><li><p><a href="/ai-ml/ai-ml-learning.html">AI and ML</a> - A comprehensive guide to getting started with AI and ML.</p></li><li><p><a href="#ml-section">Section</a></p></li><li><p><a href="/ai-ml/ai-ethics.html">discussion</a></p></li><li><p>[## Chat Large Language Models (LLMs)</p></li></ul><h3 id="higher-enclaves" tabindex="-1">Higher Enclaves <a class="header-anchor" href="#higher-enclaves" aria-label="Permalink to &quot;Higher Enclaves&quot;">​</a></h3><p>Search for &quot;AI on Government Systems&quot; on intellipedia on any enclave to find the latest information on AI tools, resources, and templates... allegedly.</p><h3 id="nipr-level-llms" tabindex="-1">NIPR Level LLMs <a class="header-anchor" href="#nipr-level-llms" aria-label="Permalink to &quot;NIPR Level LLMs&quot;">​</a></h3><ul><li>NIPRGPT: <a href="https://niprgpt.mil/" target="_blank" rel="noreferrer">https://niprgpt.mil/</a></li></ul><p>Context:</p><ul><li><p><a href="https://www.af.mil/News/Article-Display/Article/3800809/department-of-the-air-force-launches-niprgpt/" target="_blank" rel="noreferrer">https://www.af.mil/News/Article-Display/Article/3800809/department-of-the-air-force-launches-niprgpt/</a></p></li><li><p>AskSAGE: <a href="https://chat.asksage.ai/" target="_blank" rel="noreferrer">https://chat.asksage.ai/</a> It is back. <s>Currently blocked on SOCOM NIPR. 20240716</s></p></li></ul><h3 id="local-llm" tabindex="-1">Local LLM <a class="header-anchor" href="#local-llm" aria-label="Permalink to &quot;Local LLM&quot;">​</a></h3><ul><li><p>LM Studio: <a href="https://lmstudio.ai/" target="_blank" rel="noreferrer">https://lmstudio.ai/</a> Works with MacOS (M1 and Higher), Windows, and Linux. See the community guide for LM Studio](/ai-ml/ai-prompting).</p></li><li><p>Ollama: <a href="https://ollama.com" target="_blank" rel="noreferrer">https://ollama.com</a>. See the <a href="/general/ollama.html">guide for Ollama</a>.</p></li><li><p>Continue AI Coding: <a href="https://marketplace.visualstudio.com/items?itemName=Continue.continue" target="_blank" rel="noreferrer">https://marketplace.visualstudio.com/items?itemName=Continue.continue</a>. Works with Ollama and VS Code to provide coding support and autocomplete.</p></li></ul><h3 id="gpt-automation-and-prompt-engineering" tabindex="-1">GPT Automation and Prompt Engineering <a class="header-anchor" href="#gpt-automation-and-prompt-engineering" aria-label="Permalink to &quot;GPT Automation and Prompt Engineering&quot;">​</a></h3><p>#TODO: Create and Link to guides for developing with ChatGPT and Local LM</p><h3 id="chatgpt" tabindex="-1">ChatGPT <a class="header-anchor" href="#chatgpt" aria-label="Permalink to &quot;ChatGPT&quot;">​</a></h3><ul><li><p><a href="https://chatgpt.org/" target="_blank" rel="noreferrer">ChatGPT</a> An open-source chatbot platform for custom chatbot applications.</p></li><li><p><a href="https://nordnet.blob.core.windows.net/bilde/20-Effective-ChatGPT-Prompts.pdf" target="_blank" rel="noreferrer">Prompt Templates</a> from Nordnet.</p></li></ul><h3 id="gemini-formerly-bard" tabindex="-1">Gemini (Formerly Bard) <a class="header-anchor" href="#gemini-formerly-bard" aria-label="Permalink to &quot;Gemini (Formerly Bard)&quot;">​</a></h3><ul><li><a href="https://gemini.google.com/" target="_blank" rel="noreferrer">Gemini</a> - Google’s LLM chatbot (Formerly Bard).</li></ul><h3 id="perplexity-ai" tabindex="-1">Perplexity AI <a class="header-anchor" href="#perplexity-ai" aria-label="Permalink to &quot;Perplexity AI&quot;">​</a></h3><ul><li><a href="https://labs.perplexity.ai/" target="_blank" rel="noreferrer">Perplexity AI</a> - Meta’s LLM project, accessible without login.</li></ul><h3 id="content-generation-llms" tabindex="-1">Content Generation LLMs <a class="header-anchor" href="#content-generation-llms" aria-label="Permalink to &quot;Content Generation LLMs&quot;">​</a></h3><h3 id="dream-studio" tabindex="-1">Dream Studio <a class="header-anchor" href="#dream-studio" aria-label="Permalink to &quot;Dream Studio&quot;">​</a></h3><ul><li><p><a href="https://dreamstudio.ai/generate" target="_blank" rel="noreferrer">Dream Studio</a> - No login required for content generation.</p></li><li><p>AI Logo and Icon Generator: <a href="https://perchance.org/ai-icon-generator" target="_blank" rel="noreferrer">https://perchance.org/ai-icon-generator</a>.</p></li></ul><h3 id="midjourney" tabindex="-1">Midjourney <a class="header-anchor" href="#midjourney" aria-label="Permalink to &quot;Midjourney&quot;">​</a></h3><ul><li><a href="https://midjourney.com/" target="_blank" rel="noreferrer">Midjourney</a> - A tool for writing enhancement that is compatible with various platforms.</li></ul><h3 id="ai-llm-repositories" tabindex="-1">AI / LLM Repositories <a class="header-anchor" href="#ai-llm-repositories" aria-label="Permalink to &quot;AI / LLM Repositories&quot;">​</a></h3><ul><li><p><a href="https://doc.clickup.com/25598832/d/h/rd6vg-14247/0b79ca1dc0f7429/rd6vg-12207" target="_blank" rel="noreferrer">AI Master List Tool</a> - Comprehensive list of AI/LLM tools.</p></li><li><p><a href="https://github.com/mehmetkahya0/ai-catalog" target="_blank" rel="noreferrer">AI Catalog Repo</a> - Curated list of AI tools and resources.</p></li><li><p><a href="https://github.com/amusi/awesome-ai-awesomeness" target="_blank" rel="noreferrer">Awesome Generative AI</a> - A collection of resources on generative AI.</p></li><li><p><a href="https://futuretools.io" target="_blank" rel="noreferrer">FutureTools</a> - Discover the latest in AI/ML tools and services.</p></li></ul><h3 id="compare-large-language-models" tabindex="-1">Compare Large Language Models <a class="header-anchor" href="#compare-large-language-models" aria-label="Permalink to &quot;Compare Large Language Models&quot;">​</a></h3><ul><li><a href="https://chat.lmsys.org/?arena" target="_blank" rel="noreferrer">LLM Comparison</a> - Leaderboard and ratings of various LLMs.</li></ul><h3 id="prompt-programs-for-gpt" tabindex="-1">Prompt Programs for GPT <a class="header-anchor" href="#prompt-programs-for-gpt" aria-label="Permalink to &quot;Prompt Programs for GPT&quot;">​</a></h3><h3 id="gpt3-playground" tabindex="-1">GPT3 Playground <a class="header-anchor" href="#gpt3-playground" aria-label="Permalink to &quot;GPT3 Playground&quot;">​</a></h3><ul><li><a href="https://playground.openai.com/" target="_blank" rel="noreferrer">GPT3 Playground</a> - Experiment with OpenAI’s GPT-3 in various formats.</li></ul><h3 id="gpt3-terminal-tool" tabindex="-1">GPT3 Terminal Tool <a class="header-anchor" href="#gpt3-terminal-tool" aria-label="Permalink to &quot;GPT3 Terminal Tool&quot;">​</a></h3><ul><li><a href="https://git.irregularchat.com/jumson/chatgpt-search/" target="_blank" rel="noreferrer">GPT3 Terminal Tool</a> - A terminal-based tool for GPT3 integration.</li></ul><h3 id="writer" tabindex="-1">Writer <a class="header-anchor" href="#writer" aria-label="Permalink to &quot;Writer&quot;">​</a></h3><ul><li><p><a href="https://writer.com/" target="_blank" rel="noreferrer">Writer</a> - AI writing assistant.</p></li><li><p><a href="https://writer.com/ai-content-detector/" target="_blank" rel="noreferrer">Writer AI Detector</a> - Detect AI-generated content.</p></li></ul><h3 id="github-co-pilot" tabindex="-1">Github Co-Pilot <a class="header-anchor" href="#github-co-pilot" aria-label="Permalink to &quot;Github Co-Pilot&quot;">​</a></h3><ul><li><a href="https://github.com/features/copilot" target="_blank" rel="noreferrer">Github Co-Pilot</a> - Enhance Github navigation and usage.</li></ul><h3 id="ideogram-ai" tabindex="-1">Ideogram AI <a class="header-anchor" href="#ideogram-ai" aria-label="Permalink to &quot;Ideogram AI&quot;">​</a></h3><ul><li><a href="https://ideogram.ai/" target="_blank" rel="noreferrer">Ideogram AI</a> - Creative AI tools for more accessible expression.</li></ul><h2 id="ai-terminology-cheat-sheet" tabindex="-1">AI Terminology Cheat Sheet <a class="header-anchor" href="#ai-terminology-cheat-sheet" aria-label="Permalink to &quot;AI Terminology Cheat Sheet&quot;">​</a></h2><p>Also referenced in the <a href="/general/terms.html">section</a>.</p><h3 id="life" tabindex="-1">Life <a class="header-anchor" href="#life" aria-label="Permalink to &quot;Life&quot;">​</a></h3><ul><li><p><strong>Life:</strong> Process that can retain its complexity and replicate.</p></li><li><p><strong>Life 1.0:</strong> Life that evolves its hardware and software (biological stage).</p></li><li><p><strong>Life 2.0:</strong> Life that evolves its hardware but designs much of its software (cultural stage).</p></li><li><p><strong>Life 3.0:</strong> Life that designs its hardware and software (technological stage).</p></li></ul><h3 id="intelligence" tabindex="-1">Intelligence <a class="header-anchor" href="#intelligence" aria-label="Permalink to &quot;Intelligence&quot;">​</a></h3><ul><li><p><strong>Intelligence:</strong> Ability to accomplish complex goals.</p></li><li><p><strong>Artificial Intelligence (AI):</strong> Non-biological intelligence.</p></li><li><p><strong>Narrow intelligence:</strong> Ability to accomplish a narrow set of goals, e.g., play chess or drive a car.</p></li><li><p><strong>General intelligence:</strong> Ability to accomplish virtually any goal, including learning.</p></li><li><p><strong>Universal intelligence:</strong> Ability to acquire general intelligence given access to data and resources.</p></li><li><p><strong>[Artificial General Intelligence (AGI):</strong> Ability to accomplish any cognitive task at least as well as humans.</p></li><li><p><strong>Human-level AI:</strong> AGI.</p></li><li><p><strong>Strong AI:</strong> AGI.</p></li><li><p><strong>Superintelligence:</strong> General intelligence far beyond human level.</p></li></ul><h3 id="civilization" tabindex="-1">Civilization <a class="header-anchor" href="#civilization" aria-label="Permalink to &quot;Civilization&quot;">​</a></h3><ul><li><strong>Civilization:</strong> Interacting group of intelligent life forms.</li></ul><h3 id="consciousness" tabindex="-1">Consciousness <a class="header-anchor" href="#consciousness" aria-label="Permalink to &quot;Consciousness&quot;">​</a></h3><ul><li><p><strong>Consciousness:</strong> Subjective experience.</p></li><li><p><strong>Qualia:</strong> Individual instances of subjective experience.</p></li></ul><h3 id="ethics" tabindex="-1">Ethics <a class="header-anchor" href="#ethics" aria-label="Permalink to &quot;Ethics&quot;">​</a></h3><ul><li><strong>Ethics:</strong> Principles that govern how we should behave.</li></ul><h3 id="teleology" tabindex="-1">Teleology <a class="header-anchor" href="#teleology" aria-label="Permalink to &quot;Teleology&quot;">​</a></h3><ul><li><p><strong>Teleology:</strong> Explanation of things in terms of their goals or purposes rather than their causes.</p></li><li><p><strong>Goal-oriented behavior:</strong> Behavior more easily explained via its effect than via its cause.</p></li><li><p><strong>Having a goal:</strong> Exhibiting goal-oriented behavior.</p></li><li><p><strong>Having purpose:</strong> Serving goals of one’s own or of another entity.</p></li><li><p><strong>Friendly AI:</strong> Superintelligence whose goals are aligned with ours.</p></li><li><p><strong>Cyborg:</strong> Human-machine hybrid.</p></li><li><p><strong>Intelligence explosion:</strong> Recursive self-improvement rapidly leading to superintelligence.</p></li><li><p><strong>Singularity:</strong> Intelligence explosion.</p></li></ul><h3 id="universe" tabindex="-1">Universe <a class="header-anchor" href="#universe" aria-label="Permalink to &quot;Universe&quot;">​</a></h3><ul><li><strong>Universe:</strong> The region of space from which light has had time to reach us during the 13.8 billion years since our Big Bang.</li></ul><p>Tegmark, M. (2017). <em>Life 3.0: Being Human in the Age of Artificial Intelligence</em>.</p>',58)])])}const d=a(l,[["render",o]]);export{u as __pageData,d as default};
